                            <div key={msg.id} className="message-card">
                                <strong>{msg.nome}:</strong> {msg.mensagem}
                            </div>
                        ))}
                    </div>
                </>
            ) : (
                <>
                    {/* TELA 2: Mensagem Confirmada */}
                    <div className="success-display">
                        <h2>✨ Mensagem Recebida com Sucesso! ✨</h2>
                        {/* Aqui você exibiria a mensagem específica que foi paga */}
                        <div className="final-message">{messages[messages.length - 1]?.nome}: {messages[messages.length - 1]?.mensagem}</div>
                        <p>Obrigado por celebrar conosco!</p>
                    </div>
                </>
            )}
        </div>
    );
}

export default DisplaySystem;
```

